package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen2Test {

    @Test
    public void testAppendWithValidHtml() {
        Element parent = new Element(Tag.valueOf("div"), "");
        String html = "<p>Hello</p><span>World</span>";

        Element result = parent.append(html);

        // Check return type is 'this'
        Assert.assertEquals(parent, result);

        // Check children were appended
        Assert.assertEquals(2, parent.children().size());
        Assert.assertEquals("p", parent.child(0).tagName());
        Assert.assertEquals("span", parent.child(1).tagName());
        Assert.assertEquals("Hello", parent.child(0).text());
        Assert.assertEquals("World", parent.child(1).text());

        // Check parent-child relationship is correctly established
        Assert.assertEquals(parent, parent.child(0).parent());
        Assert.assertEquals(parent, parent.child(1).parent());
    }

    @Test
    public void testAppendWithTextNode() {
        Element parent = new Element(Tag.valueOf("div"), "");
        String html = "Just text";

        parent.append(html);

        // Parser.parseBodyFragment for "Just text" results in a TextNode inside the body
        Assert.assertEquals(1, parent.childNodes().size());
        Assert.assertEquals("Just text", parent.child(0).text());
    }

    @Test
    public void testAppendWithEmptyHtml() {
        Element parent = new Element(Tag.valueOf("div"), "");
        String html = "";

        parent.append(html);

        // Depending on parser behavior, empty string might result in no children or an empty text node
        // In jsoup, parseBodyFragment("") results in an empty body
        Assert.assertTrue(parent.childNodes().isEmpty() || parent.text().isEmpty());
    }

    @Test(expected = NullPointerException.class)
    public void testAppendWithNullHtml() {
        Element parent = new Element(Tag.valueOf("div"), "");
        // Validate.notNull throws NullPointerException
        parent.append(null);
    }

    @Test
    public void testAppendComplexStructure() {
        Element parent = new Element(Tag.valueOf("ul"), "");
        String html = "<li>Item 1</li><li class='active'>Item 2</li>";

        parent.append(html);

        Assert.assertEquals(2, parent.children().size());
        Assert.assertTrue(parent.child(1).hasClass("active"));
        Assert.assertEquals("Item 1", parent.child(0).text());
        Assert.assertEquals("Item 2", parent.child(1).text());
    }

    @Test
    public void testAppendMaintainsOriginalChildren() {
        Element parent = new Element(Tag.valueOf("div"), "");
        parent.appendElement("span");

        String html = "<b>New</b>";
        parent.append(html);

        Assert.assertEquals(2, parent.children().size());
        Assert.assertEquals("span", parent.child(0).tagName());
        Assert.assertEquals("b", parent.child(1).tagName());
    }
}
